export type Severity = 'High' | 'Medium' | 'Low';

export interface GapItem {
  name: string;
  severity: Severity;
  evidence: string[];
}

export interface SetupInfo {
  name: string;
  summary: string;
  alternatives: string[];
}

export interface ConfigOption {
  id: string;
  label: string;
  description: string;
  cost: number;
  recommended: boolean;
}

export interface ConfigGroup {
  title: string;
  gap?: Severity;
  fromSetup?: boolean;
  options: ConfigOption[];
}

export interface GeneratedFile {
  path: string;
  folder: string;
  content: string;
}

