function folderOf(path: string): string {
  const i = path.lastIndexOf('/');
  return i === -1 ? '' : path.slice(0, i);
}

export function generateFiles(selected: Set<string>): GeneratedFile[] {
  return FILE_DEFS.filter((f) => selected.has(f.requires)).map((f) => ({
    path: f.path,
    folder: folderOf(f.path),
    content: f.content,
  }));
}
